INSERT INTO analysis (property_id,due_diligence_score,seller_weakness_score,acquisition_score,risk_score,upside_score,overall_score,recommendation,missing_items,weaknesses)
SELECT * FROM (VALUES
  (-1625618::bigint,58,67,74,61,78,70,'PURSUE / REQUEST FULL DILIGENCE. Attractive 7.09% current cap with pro forma upside, but the package is only a one-page rent-roll summary and includes vacancy, near-term lease events, temporary rent abatement, and an HVAC condition obligation.','Full OM; T12; executed leases; tax and insurance backup; CAM/NNN reconciliation; roof/HVAC reports; environmental report; tenant ledger; land size; year built.','13.3% vacancy; thin source package; Texas Leather temporary abatement and HVAC obligation; Bintelli and LouPai lease rollover; operating expenses unavailable.'),
  (-2349164,82,56,82,43,67,77,'PURSUE / VERIFY DEBT AND TENANT QUALITY. 100% occupied 2018 retail center at a 7.30% cap with assumable 6.75% debt, but near-term lease expirations, tenant credit quality, and loan-assumption mechanics must be verified.','T12; executed leases; tenant ledger; CAM reconciliations; loan documents and assumption requirements; tax/insurance backup; roof/HVAC reports; environmental report.','Multiple expirations in 2027-2028; service/local tenant credit exposure; high rent PSF should be tested against market; debt assumption is subject to lender approval.'),
  (-2621733,84,74,77,56,76,75,'PURSUE / VERIFY MASTER LEASE. Fresenius provides a strong corporate-guaranteed medical anchor and recent capital improvements, but 21.2% of the building is physically vacant and the 6.99% cap depends on seller master-lease income.','Seller master-lease agreement and guaranty; leasing pipeline for vacant suite; T12; Fresenius lease documents; tax/insurance backup; roof/HVAC warranties; environmental report; tenant ledger.','21.2% physical vacancy; seller master lease supports underwriting; 78.8% concentration in Fresenius; verify 2025 capital work and warranties.'),
  (-2465894,80,92,84,79,97,85,'PURSUE AS VALUE-ADD / PRICE FOR LEASE-UP RISK. The asset has substantial upside but is only 47.4% occupied and produces an approximately 3.24% Year-1 cap at the OM price. Acquisition value depends heavily on leasing execution and capital requirements.','Current leasing pipeline and LOIs; T12; rent roll Excel; leases/amendments; tenant ledger; CAM reconciliation; capex history; roof/HVAC/plumbing/electrical reports; environmental report; tax/insurance backup; seller reason for sale.','52.6% vacancy; low current yield; older 1970/1973 construction; pro forma assumes meaningful annual lease-up; several near-term tenant expirations.'),
  (-1900377375,86,48,79,44,66,76,'PURSUE / VERIFY TENANT CREDIT AND ROLLOVER. New 2024 Class A retail at 100% occupancy and 6.60% cap is attractive for stability, but 49.6% of NRA rolls in 2030 and the tenant mix includes several local concepts.','T12; executed leases; tenant sales/credit; payment ledger; CAM reconciliations; tax/insurance invoices; confirm Wing Bay expiration; roof/HVAC warranties; environmental report.','49.6% rollover in 2030; local tenant concentration; ownership-projected expenses; Wing Bay expiration inconsistency in OM; tighter 6.60% going-in cap.')
) AS v(property_id,due_diligence_score,seller_weakness_score,acquisition_score,risk_score,upside_score,overall_score,recommendation,missing_items,weaknesses)
WHERE NOT EXISTS (SELECT 1 FROM analysis a WHERE a.property_id=v.property_id);

INSERT INTO committee_reports (property_id,report)
SELECT * FROM (VALUES
  ('26333_i45_n_spring_tx_2026',jsonb_build_object('summary','26333 I-45 N is offered at $4.0M with $283,692 current NOI, 7.09% current cap, 86.7% occupancy and $328,692 pro forma NOI. Three suites are occupied and one 1,800 SF suite is vacant. The one-page source shows useful lease detail but no operating expense statement.','decision','PURSUE / REQUEST FULL DILIGENCE','broker_questions',jsonb_build_array('Please send the complete OM, T12 and current rent roll in Excel.','Please send all executed leases and amendments.','Confirm current NNN charges and recoveries by tenant.','Confirm Suite 3 rent-abatement dates and HVAC work required before commencement.','Provide tax, insurance, roof/HVAC and environmental reports.','Are all occupied tenants current on rent?','What is the leasing activity for the 1,800 SF vacancy?','What is the seller reason for sale?'))),
  ('little_york_plaza_houston_tx_2026',jsonb_build_object('summary','Little York Plaza is a 19,525 SF, 2018-built, 100% occupied multi-tenant retail center offered at $8.5M and a 7.30% cap. The OM shows $624,669 NOI and approximately $4.847M of assumable debt at 6.75%.','decision','PURSUE / VERIFY DEBT AND TENANT QUALITY','broker_questions',jsonb_build_array('Please send T12 and current rent roll in Excel.','Please send all executed leases and amendments.','Provide the full assumable loan package, lender transfer requirements and any assumption fee.','Are all tenants current on rent?','Provide CAM reconciliation history and current NNN estimates.','Provide tenant sales/credit where available.','Provide tax, insurance, roof/HVAC and environmental reports.','What is the seller reason for sale?'))),
  ('copper_grove_corner_houston_tx_2026',jsonb_build_object('summary','Copper Grove Corner is a 14,000 SF medical-anchored property offered at $3.2M and a 6.99% cap. Fresenius occupies 11,036 SF under a corporate-guaranteed lease through October 2033; the remaining 2,964 SF is physically vacant but underwritten with a seller master lease at $24/SF NNN.','decision','PURSUE / VERIFY MASTER LEASE','broker_questions',jsonb_build_array('Please send the executed seller master lease and guaranty.','What active prospects, tours or LOIs exist for the 2,964 SF available suite?','Please send T12 and expense backup.','Please send the executed Fresenius lease and 2025 amendment.','Confirm completion and warranties for roof, HVAC, parking and other 2025 work.','Provide tax, insurance and environmental reports.','Is Fresenius fully current on rent?','What is the seller reason for sale?'))),
  ('fm_1960_6410_6578_houston_tx_2026',jsonb_build_object('summary','6410-6578 FM 1960 is a 136,738 SF, 13.79-acre value-add retail center offered at $13.4M. It is only 47.4% occupied, with $434,374 Year-1 NOI and an implied Year-1 cap of roughly 3.24%. The OM projects NOI growth to $1.84M by Year 10 through lease-up.','decision','PURSUE AS VALUE-ADD / PRICE FOR LEASE-UP RISK','broker_questions',jsonb_build_array('Please send the current rent roll in Excel and T12.','Which vacant suites have active LOIs, tours or proposals?','What tenant-improvement and leasing-commission assumptions are required to achieve the lease-up plan?','Provide all executed leases and amendments.','Provide tenant payment ledger and delinquency report.','Provide full capex history and roof/HVAC/plumbing/electrical reports.','Provide tax, insurance, CAM reconciliation and environmental reports.','Why is the seller exiting at 52.6% vacancy?'))),
  ('market_at_northpointe_tomball_tx_2026',jsonb_build_object('summary','Market at Northpointe is a 17,261 SF Class A retail center built in 2024 and offered at $8.595M. The OM reports 100% occupancy, $567,458 NOI and a 6.60% cap with seven tenants and six years average remaining term.','decision','PURSUE / VERIFY TENANT CREDIT AND ROLLOVER','broker_questions',jsonb_build_array('Please send T12 and current rent roll in Excel.','Please send all executed leases and amendments.','Please provide tenant sales and credit information.','Confirm Wing Bay lease expiration because the rent roll and rollover schedule appear inconsistent.','Provide CAM reconciliation and NNN estimate history.','Provide tax and insurance invoices.','Provide roof/HVAC warranties for the 2024 construction.','Are all tenants current on rent?','What is the seller reason for sale?')))
) AS v(property_id,report)
WHERE NOT EXISTS (SELECT 1 FROM committee_reports c WHERE c.property_id=v.property_id);

INSERT INTO acquisition_decisions (property_id,decision)
SELECT * FROM (VALUES
  ('26333_i45_n_spring_tx_2026',jsonb_build_object('decision','PURSUE / REQUEST FULL DILIGENCE','next_action','Request complete OM, T12, rent roll Excel, executed leases, NNN reconciliation, tax/insurance, roof/HVAC, environmental report and vacancy leasing pipeline.','offer_posture','Do not price off the 8.217% pro forma cap until vacancy lease-up, abatement and HVAC obligations are verified.')),
  ('little_york_plaza_houston_tx_2026',jsonb_build_object('decision','PURSUE / VERIFY DEBT AND TENANT QUALITY','next_action','Obtain T12, leases, tenant ledger, CAM reconciliations and the complete assumable-debt package before underwriting final debt service and cash-on-cash returns.','offer_posture','Potentially attractive stabilized acquisition; preserve pricing discipline around 2027-2028 lease rollover and loan-assumption conditions.')),
  ('copper_grove_corner_houston_tx_2026',jsonb_build_object('decision','PURSUE / VERIFY MASTER LEASE','next_action','Obtain executed seller master lease/guaranty, Fresenius lease documents, T12, leasing pipeline for the vacant suite and 2025 capital-work warranties.','offer_posture','Underwrite durable value using physical occupancy and realistic lease-up economics, not seller master-lease income alone.')),
  ('fm_1960_6410_6578_houston_tx_2026',jsonb_build_object('decision','PURSUE AS VALUE-ADD / PRICE FOR LEASE-UP RISK','next_action','Build a detailed lease-up budget with TI, LC, free rent, downtime and capital repairs after receiving current leasing pipeline, T12, leases and building-condition reports.','offer_posture','Current yield is too low for the asking price without successful lease-up; negotiate based on as-is NOI, vacancy carrying cost and required capital.')),
  ('market_at_northpointe_tomball_tx_2026',jsonb_build_object('decision','PURSUE / VERIFY TENANT CREDIT AND ROLLOVER','next_action','Obtain leases, T12, tenant sales/credit, CAM reconciliations and confirm Wing Bay expiration before finalizing rollover and credit underwriting.','offer_posture','Strong newer stabilized asset, but price for concentrated 2030 rollover and local-tenant credit rather than assuming automatic renewals.'))
) AS v(property_id,decision)
WHERE NOT EXISTS (SELECT 1 FROM acquisition_decisions a WHERE a.property_id=v.property_id);

COMMIT;

